// VERIFY-1: /verification and /api/verification, rendered from the generated module (regenerated by `verify --data --apply`, checked in `checks`).
import V from "./verification-data.js";
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
export function verificationJson() { return V; }
export function verificationBody() {
  const c = V.coverage;
  const rows = V.invariants.map(i => `<tr><td>${esc(i.id)}</td><td>${i.model_checked ? "yes" : "no"}</td><td>${i.code_conformance ? "yes" : "no"}</td><td>${esc(i.runtime_monitor || "")}</td><td>${i.source.map(s => esc(V.sources[s] || s)).join("<br>")}</td></tr>`).join("");
  const models = Object.entries(V.models).map(([k, m]) => `<li>${esc(k)}: ${m.ok ? "passes" : "fails"}${m.states != null ? ` (${m.states} states or samples)` : ""}</li>`).join("");
  return `<h1>Verified invariants</h1><p>${c.tied_to_code} of ${c.invariants} guarantees are model-checked and tied to the deployed code (${Math.round(c.share * 100)}%). Every state of each model is explored for safety, deadlock and liveness on every change.</p><ul>${models}</ul><div style="overflow-x:auto"><table><thead><tr><th>Guarantee</th><th>Model-checked</th><th>Code conformance</th><th>Monitor</th><th>Source</th></tr></thead><tbody>${rows}</tbody></table></div>`;
}
